import React, { useState } from 'react';
import logo from '../../../assets/logo.png';

function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  return (
    <header className="bg-[#FDF8F3] border-b border-[#E1D5C9] p-4">
      <div className="flex items-center justify-between md:relative flex-wrap">
        {/* Logo */}
        <img src={logo} alt="Logo" className="h-12" />

        {/* Mobile Menu Toggle */}
        <div className="md:hidden ml-auto">
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="text-2xl font-bold"
          >
            ☰
          </button>
        </div>

        {/* Desktop nav (centered), button (right) */}
        <div
          className={`w-full md:flex md:items-center md:justify-center md:gap-8 mt-4 md:mt-0 ${
            isMenuOpen ? 'block' : 'hidden'
          }`}
        >
          {/* Nav links - centered in desktop */}
          <nav className="flex flex-col md:flex-row items-center gap-4 text-[clamp(0.9rem,2vw,1.1rem)] font-semibold text-[#292929] w-full md:w-auto md:mx-auto">
            <a href="#" className="text-[#f48f0f]">Home</a>
            <a href="#">About</a>
            <a href="#">Gallery</a>
            <a href="#">Education</a>
          </nav>
        </div>

        {/* Become Member Button - right aligned on desktop */}
        <div className="hidden md:block absolute right-4 top-1/2 -translate-y-1/2">
          <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
            Become a member
          </button>
        </div>

        {/* Mobile button below nav */}
        {isMenuOpen && (
          <div className="md:hidden mt-4 flex justify-center w-full">
            <button className="bg-[#F48F0F] text-[#292929] px-4 py-2 rounded-full font-semibold text-[clamp(0.9rem,2vw,1rem)]">
              Become a member
            </button>
          </div>
        )}
      </div>
    </header>
  );
}

export default Navbar;
